import{is,getBusinessObject}from"./ModelUtil";import{forEach}from"min-dash";export function isExpanded(n){return!is(n,"bpmn:CallActivity")&&(is(n,"bpmn:SubProcess")?!!getBusinessObject(n).di.isExpanded:!is(n,"bpmn:Participant")||!!getBusinessObject(n).processRef)}export function isInterrupting(n){return n&&!1!==getBusinessObject(n).isInterrupting}export function isEventSubProcess(n){return n&&!!getBusinessObject(n).triggeredByEvent}export function hasEventDefinition(n,t){var e=getBusinessObject(n),i=!1;return e.eventDefinitions&&forEach(e.eventDefinitions,function(n){is(n,t)&&(i=!0)}),i}export function hasErrorEventDefinition(n){return hasEventDefinition(n,"bpmn:ErrorEventDefinition")}export function hasEscalationEventDefinition(n){return hasEventDefinition(n,"bpmn:EscalationEventDefinition")}export function hasCompensateEventDefinition(n){return hasEventDefinition(n,"bpmn:CompensateEventDefinition")}